INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the function of the ''grid bar'' or ''mote knife'' in the carding machine''s licker-in zone?', '["To help separate and remove heavier trash particles from the fiber stream during initial opening on the card","To insert twist into the sliver","To wind the finished sliver into a can","To dye the raw fiber before carding"]'::jsonb, 'To help separate and remove heavier trash particles from the fiber stream during initial opening on the card', 'In the licker-in zone, grid bars/mote knives work with centrifugal force to let heavier trash particles fall away from the lighter fiber as it''s carried on the licker-in, aiding early-stage cleaning.', 1, '{"carding","licker-in"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the ''cylinder'' in a carding machine primarily responsible for?', '["Carrying and further individualizing/aligning fibers received from the licker-in, working with the flats","Winding the final sliver into a can","Measuring yarn count","Dyeing the cotton fiber"]'::jsonb, 'Carrying and further individualizing/aligning fibers received from the licker-in, working with the flats', 'The main cylinder, covered in fine card clothing, carries fiber at high speed and works with the flats (or in some designs, other cylinders) to open fiber tufts into individual fibers and remove remaining trash/neps.', 1, '{"carding","cylinder"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What are the ''flats'' in a revolving-flat carding machine?', '["A slow-moving series of bars covered with card clothing that work against the cylinder to further card the fiber","The final output rollers that form sliver","The bale-opening mechanism","The twist-inserting mechanism"]'::jsonb, 'A slow-moving series of bars covered with card clothing that work against the cylinder to further card the fiber', 'Flats are a continuous chain of bars with fine wire clothing that move slowly over the main cylinder, carding the fiber caught between them and the cylinder, and collecting short fiber/trash as ''flat strips''.', 1, '{"carding","flats"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What does the ''doffer'' do in a carding machine?', '["It strips the carded fiber web off the main cylinder to be condensed into sliver","It opens raw cotton bales","It twists roving into yarn","It cleans finished fabric"]'::jsonb, 'It strips the carded fiber web off the main cylinder to be condensed into sliver', 'The doffer is a slower-rotating cylinder that collects the thin carded fiber web from the main cylinder; this web is then condensed and coiled into a sliver via the trumpet and calendar rollers.', 1, '{"carding","doffer"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the general purpose of a ''coiler'' at the end of the carding or drawing machine?', '["To coil the delivered sliver neatly into a rotating can for storage/transport","To insert twist into the final yarn","To open raw fiber bales","To dye the sliver before further processing"]'::jsonb, 'To coil the delivered sliver neatly into a rotating can for storage/transport', 'The coiler mechanism lays the continuously delivered sliver in neat, overlapping coils inside a rotating sliver can, allowing large lengths of sliver to be stored/transported without tangling.', 1, '{"coiler","sliver-can"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Why is sliver stored/transported in circular cans rather than simply wound onto a bobbin like yarn?', '["Sliver has no twist and would tangle or distort if wound under tension like yarn; coiling loosely into a can avoids stretching it","Cans are only used for decorative purposes with no functional benefit","Sliver is too thin to be handled in any other way","Bobbins cannot physically hold any textile material"]'::jsonb, 'Sliver has no twist and would tangle or distort if wound under tension like yarn; coiling loosely into a can avoids stretching it', 'Since sliver is untwisted and fragile, winding it under tension (as with yarn) would stretch or distort it; loose coiling into a can preserves its state for later drafting without added tension.', 1, '{"sliver-handling"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the primary role of humidity (relative humidity) control in a spinning mill''s carding/spinning department?', '["To keep fiber moisture at a level that minimizes static electricity and fiber breakage during high-speed processing","To directly change the color of the fiber","To eliminate the need for any twist insertion","To permanently increase fiber staple length"]'::jsonb, 'To keep fiber moisture at a level that minimizes static electricity and fiber breakage during high-speed processing', 'Controlled humidity keeps fibers pliable and conductive enough to prevent static buildup (which causes fiber clinging/flying) while avoiding excess moisture that causes fiber slippage or machine issues — both extremes disrupt smooth processing.', 1, '{"humidity-control"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What does ''yarn tenacity'' typically refer to in textile testing?', '["The breaking strength of yarn expressed relative to its linear density (e.g., grams-force per tex)","The color fastness of dyed yarn","The twist direction of the yarn","The exact weight of one yarn package"]'::jsonb, 'The breaking strength of yarn expressed relative to its linear density (e.g., grams-force per tex)', 'Tenacity normalizes breaking force by the yarn''s linear density (count), allowing fair strength comparison between yarns of different thicknesses — commonly expressed in g/tex or cN/tex.', 1, '{"tenacity"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''elongation at break'' for a yarn?', '["The percentage increase in yarn length at the moment it breaks under tension, relative to its original length","The final twist level of a broken yarn","The color change observed just before breaking","The weight loss of yarn during testing"]'::jsonb, 'The percentage increase in yarn length at the moment it breaks under tension, relative to its original length', 'Elongation at break (%) = (extended length at break − original length) / original length × 100 — it indicates how much a yarn stretches before failing, important for end-use performance like knitting or weaving stress.', 1, '{"elongation"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Which of the following is generally considered an advantage of synthetic staple fiber (e.g., polyester) blended with cotton in ring spinning?', '["Improved yarn strength and reduced shrinkage/wrinkling compared to 100% cotton","Synthetic fiber always reduces yarn strength versus 100% cotton","Blending always eliminates the need for any twist","Synthetic fiber cannot be spun on a ring frame at all"]'::jsonb, 'Improved yarn strength and reduced shrinkage/wrinkling compared to 100% cotton', 'Polyester generally has higher tenacity and better dimensional stability than cotton; blending it in typically improves overall yarn/fabric strength and reduces shrinkage and wrinkling versus 100% cotton.', 1, '{"blended-yarn","polyester-cotton"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''S-twist'' versus ''Z-twist'' in yarn?', '["They describe the direction of twist (diagonal slant of fibers) as viewed when the yarn is held vertically — S slants like the letter S, Z like the letter Z","S-twist means synthetic fiber, Z-twist means natural fiber","They refer to two different yarn count systems","They indicate whether the yarn is combed (S) or carded (Z)"]'::jsonb, 'They describe the direction of twist (diagonal slant of fibers) as viewed when the yarn is held vertically — S slants like the letter S, Z like the letter Z', 'S and Z twist describe the visual direction the twist spirals — matching the central diagonal stroke of the letters ''S'' or ''Z'' — a fundamental, purely geometric distinction independent of fiber type or count system.', 1, '{"twist-direction"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why might a fabric use yarns with both S-twist and Z-twist in warp and weft (or alternating)?', '["To create specific surface texture effects (like crepe) or to balance torque/liveliness in the fabric","S and Z twist yarns cannot physically be woven together at all","It is purely a labeling convention with zero effect on the fabric","It only matters for the fabric''s color, not texture"]'::jsonb, 'To create specific surface texture effects (like crepe) or to balance torque/liveliness in the fabric', 'Combining S and Z twist yarns can create distinctive surface textures (e.g., crepe fabrics rely on alternating high-twist S/Z yarns) or help balance the twist-liveliness/torque of the fabric structure.', 2, '{"twist-direction","crepe"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the main reason ring-spinning speeds (spindle rpm) are ultimately limited, even with modern high-speed spindles?', '["Excessive centrifugal force/tension on the yarn balloon at very high speeds causes increased end breakage and traveler wear","There is no physical limit; speed can be increased indefinitely without consequence","Higher spindle speed always reduces yarn tension to zero","Spindle speed is limited only by dye availability"]'::jsonb, 'Excessive centrifugal force/tension on the yarn balloon at very high speeds causes increased end breakage and traveler wear', 'As spindle speed rises, the rotating yarn balloon experiences greater centrifugal force and tension; beyond an optimum point this causes more end breaks and faster traveler wear/heat, limiting practical speed increases.', 2, '{"ring-frame-speed"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is ''package density'' in the context of a wound yarn cone, and why does it matter?', '["How tightly/compactly yarn is wound onto the cone; it affects transport efficiency, unwinding behavior, and dye penetration in later processing","The exact chemical composition of the yarn fiber","The twist level inserted during ring spinning","The color depth of the dyed yarn"]'::jsonb, 'How tightly/compactly yarn is wound onto the cone; it affects transport efficiency, unwinding behavior, and dye penetration in later processing', 'Package density (how tightly yarn is packed on the cone) affects how much yarn fits per package (transport/storage efficiency), how smoothly it unwinds in downstream processes, and — for package dyeing — how evenly dye liquor can penetrate the wound yarn.', 2, '{"package-density","winding"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A yarn spinner needs to produce a much finer yarn count than their current recipe allows using the same fiber quality. Besides using better (longer/finer) fiber, what in-process change most directly enables finer counts?', '["Increasing the total draft applied through the spinning preparatory stages (draw frame, simplex, ring frame) to thin the strand further","Decreasing twist to zero","Switching only the traveler size with no other change","Reducing humidity to zero percent"]'::jsonb, 'Increasing the total draft applied through the spinning preparatory stages (draw frame, simplex, ring frame) to thin the strand further', 'Achieving a finer count requires progressively thinning (drafting) the fiber strand more across the preparatory and spinning stages; fiber quality sets the practical LIMIT of how fine you can go while maintaining adequate strength, but draft is the direct mechanism for achieving fineness.', 2, '{"fine-count-spinning"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why do spinning mills typically blend cotton from multiple bales/lots before carding rather than processing one bale at a time?', '["To average out lot-to-lot variation in fiber properties (length, maturity, color) and achieve consistent yarn quality","Blending is purely for cost accounting, with no quality purpose","Single-bale processing is physically impossible on any carding machine","Blending eliminates the need for any drafting later in the process"]'::jsonb, 'To average out lot-to-lot variation in fiber properties (length, maturity, color) and achieve consistent yarn quality', 'Individual cotton bales/lots vary in staple length, maturity, color, and trash content; blending multiple bales (bale management) averages out these differences so the resulting yarn has consistent, predictable properties.', 2, '{"bale-blending"}'::text[]);
